local function runChunk(mode, ctrl)
	local served = false
	local ok, f = pcall(load, function()
		if served then return nil end
		served = true
		return BC
	end)
	if ok ~= true or type(f) ~= "function" then return nil end
	local okR, res = pcall(f, mode, ctrl)
	if okR ~= true then return nil end
	return res
end

function LUI.createMenu.acc_lb_rec(InstanceRef)
	local Hud = CoD.Menu.NewForUIEditor("acc_lb_rec")
	Hud:setOwner(InstanceRef)
	Hud:setLeftRight(true, true, 0, 0)
	Hud:setTopBottom(true, true, 0, 0)

	-- Record + POST, blocking (we are on the game-over screen; the chunk caps curl at
	-- 6s). InstanceRef doubles as the controller for the UI-model reads (acc_hud.lua
	-- passes it to Engine.GetModelForController the same way).
	runChunk("rec", InstanceRef)

	return Hud
end
